```csharp
using UnityEngine;
using System.Collections;

public class GameManager : MonoBehaviour
{
    public int gridWidth = 8;
    public int gridHeight = 8;
    public GameObject[] tiles;
    public int score = 0;

    private Grid[,] grid;

    void Start()
    {
        grid = new Grid[gridWidth, gridHeight];
        for (int i = 0; i < gridWidth; i++)
        {
            for (int j = 0; j < gridHeight; j++)
            {
                grid[i, j] = new Grid(i, j);
            }
        }
    }

    void Update()
    {
        // Comprueba si se ha producido un match
        Match();
    }

    void Match()
    {
        // Comprueba todas las casillas adyacentes
        for (int i = 0; i < gridWidth; i++)
        {
            for (int j = 0; j < gridHeight; j++)
            {
                // Comprueba casillas adyacentes
                if (grid[i, j] != null && grid[i, j].type != 0)
                {
                    // Comprueba si hay un match
                    if (HasMatch(i, j))
                    {
                        // Elimina la casilla
                        Destroy(grid[i, j].gameObject);
                        // Aumenta el puntaje
                        score += 10;
                    }
                }
            }
        }
    }

    bool HasMatch(int x, int y)
    {
        // Comprueba si hay un match en las casillas adyacentes
        // (arriba, abajo, izquierda y derecha)
        for (int i = -1; i <= 1; i++)
        {
            for (int j = -1; j <= 1; j++)
            {
                if (i == 0 && j == 0) continue;
                int newX = x + i;
                int newY = y + j;
                if (newX >= 0 && newX < gridWidth && newY >= 0 && newY < gridHeight)
                {
                    Grid adjacent = grid[newX, newY];
                    if (adjacent != null && adjacent.type == grid[x, y].type)
                    {
                        // Hay un match
                        return true;
                    }
                }
            }
        }
        return false;
    }
}
```
