import React, { useState, useEffect } from 'react';

function Autocomplete(props) {
  const { suggestions, renderItem } = props;
  const [filteredSuggestions, setFilteredSuggestions] = useState([]);
  const [activeSuggestionIndex, setActiveSuggestionIndex] = useState(0);
  const [inputValue, setInputValue] = useState('');
  const [showSuggestions, setShowSuggestions] = useState(false);

  useEffect(() => {
    const handleInput = (e) => {
      const value = e.target.value;
      let newFilteredSuggestions = suggestions.filter((suggestion) => suggestion.toLowerCase().startsWith(value.toLowerCase()));
      setFilteredSuggestions(newFilteredSuggestions);
      setActiveSuggestionIndex(0);
      setInputValue(value);
      setShowSuggestions(!!newFilteredSuggestions.length);
    };
    document.addEventListener('input', handleInput);
    return () => {
      document.removeEventListener('input', handleInput);
    };
  }, [suggestions, setActiveSuggestionIndex]);

  const handleKeyDown = (e) => {
    switch (e.key) {
      case 'ArrowDown':
        setActiveSuggestionIndex((prevIndex) => (prevIndex + 1) % filteredSuggestions.length);
        break;
      case 'ArrowUp':
        setActiveSuggestionIndex((prevIndex) => (prevIndex - 1 + filteredSuggestions.length) % filteredSuggestions.length);
        break;
      case 'Enter':
        setInputValue(filteredSuggestions[activeSuggestionIndex]);
        break;
      case 'Escape':
        setInputValue('');
        break;
      default:
        break;
    }
  };

  return (
    <div>
      <input
        type="text"
        value={inputValue}
        onChange={(e) => setInputValue(e.target.value)}
        placeholder={props.placeholder}
        onKeyDown={handleKeyDown}
      />
      {showSuggestions && (
        <ul className="suggestions-list">
          {filteredSuggestions.map((suggestion, index) => (
            <li
              key={index}
              className={index === activeSuggestionIndex ? 'active' : ''}
              onClick={(e) => setInputValue(suggestion)}
            >
              {renderItem(suggestion)}
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

export default Autocomplete;
```

