        listener.Start();

        // Boucle principale pour écouter les requêtes
        while (true)
        {
            Console.WriteLine("Waiting for a request...");

            // Attendre une requête
            HttpListenerContext context = listener.GetContext();

            // Traitement de la requête
            string requestPath = context.Request.Url.AbsolutePath;
            Console.WriteLine($"Received request for: {requestPath}");

            if (requestPath == "/hello")
            {
                // Renvoyer une réponse HTTP 200 OK avec le contenu "Hello"
                context.Response.ContentType = "text/plain";
                string responseContent = "Hello";
                byte[] responseBytes = System.Text.Encoding.UTF8.GetBytes(responseContent);
                context.Response.OutputStream.Write(responseBytes, 0, responseBytes.Length);
                context.Response.OutputStream.Close();
            }
            else
            {
                // Renvoyer une réponse HTTP 404 Not Found
                context.Response.StatusCode = 404;
                context.Response.StatusDescription = "Not Found";
            }
        }
    }
}
