import React, { useState } from 'react';

function TodoList() {
  const [todos, setTodos] = useState([]);
  const [newTodo, setNewTodo] = useState('');

  const handleSubmit = (event) => {
    event.preventDefault();
    setTodos([...todos, { id: Date.now(), text: newTodo, completed: false }]);
    setNewTodo('');
  };

  const handleTodoChange = (event) => {
    setNewTodo(event.target.value);
  };

  const handleTodoDelete = (id) => {
    setTodos(todos.filter((todo) => todo.id !== id));
  };

  const handleTodoComplete = (id) => {
    setTodos(
      todos.map((todo) => (todo.id === id ? { ...todo, completed: !todo.completed } : todo))
    );
  };

  return (
    <div>
      <form onSubmit={handleSubmit}>
        <input
          type="text"
          value={newTodo}
          onChange={handleTodoChange}
          placeholder="Enter a new todo item"
        />
        <button type="submit">Add</button>
      </form>
      <ul>
        {todos.map((todo) => (
          <li key={todo.id}>
            <input
              type="checkbox"
              checked={todo.completed}
              onChange={() => handleTodoComplete(todo.id)}
            />
            <span
              style={{
                textDecoration: todo.completed ? 'line-through' : 'none',
              }}
            >
              {todo.text}
            </span>
            <button onClick={() => handleTodoDelete(todo.id)}>Delete</button>
          </li>
        ))}
      </ul>
    </div>
  );
}

export default TodoList;
```
**How it works:**

1. We use the `useState` hook to store the todos, new todo input value, and whether a todo is completed in the component state.
2. The `handleSubmit` function is called when the user submits the form, and it adds a new todo item to the list with a unique ID.
3. The `handleTodoChange` function updates the new todo input value.
4. The `handleTodoDelete` function removes a todo item from the list by filtering out the item with the matching ID.
5. The `handleTodoComplete` function toggles the completed state of a todo item.
6. The JSX renders the form, input field, and list of todo items. Each list item has a checkbox to toggle completion, a span to display the todo text, and a button to delete the item.

